macro_rules! deps {
    () => {
        SlotMapIndex!();
        MutableIndexAndPack!();
    };
}

macro_rules! Store {
    () => {
        deps!();
        # [doc = " The object store for use in any applications with support for auto-updates in the light of changes to the object database."] # [doc = ""] # [doc = " ### Features"] # [doc = ""] # [doc = " - entirely lazy, creating an instance does no disk IO at all if [`Slots::Given`][store::init::Slots::Given] is used."] # [doc = " - multi-threaded lazy-loading of indices and packs"] # [doc = " - per-thread pack and object caching avoiding cache trashing."] # [doc = " - most-recently-used packs are always first for speedups if objects are stored in the same pack, typical for packs organized by"] # [doc = "   commit graph and object age."] # [doc = " - lock-free reading for perfect scaling across all cores, and changes to it don't affect readers as long as these don't want to"] # [doc = "   enter the same branch."] # [doc = " - sync with the state on disk if objects aren't found to catch up with changes if an object seems to be missing."] # [doc = "    - turn off the behaviour above for all handles if objects are expected to be missing due to spare checkouts."] pub struct Store { # [doc = " The central write lock without which the slotmap index can't be changed."] write : parking_lot :: Mutex < () > , # [doc = " The source directory from which all content is loaded, and the central write lock for use when a directory refresh is needed."] pub (crate) path : PathBuf , # [doc = " The current working directory at the time this store was instantiated. It becomes relevant when resolving alternate paths"] # [doc = " when re-reading the store configuration on updates when an object was missed."] # [doc = " Keeping it here helps to assure consistency even while a process changes its CWD."] pub (crate) current_dir : PathBuf , # [doc = " A set of replacements that given a source OID return a destination OID. The vector is sorted."] pub (crate) replacements : Vec < (gix_hash :: ObjectId , gix_hash :: ObjectId) > , # [doc = " A list of indices keeping track of which slots are filled with data. These are usually, but not always, consecutive."] pub (crate) index : ArcSwap < types :: SlotMapIndex > , # [doc = " The below state acts like a slot-map with each slot is mutable when the write lock is held, but readable independently of it."] # [doc = " This allows multiple file to be loaded concurrently if there is multiple handles requesting to load packs or additional indices."] # [doc = " The map is static and cannot change."] # [doc = " It's read often and changed rarely."] pub (crate) files : Vec < types :: MutableIndexAndPack > , # [doc = " The amount of handles that would prevent us from unloading packs or indices"] pub (crate) num_handles_stable : AtomicUsize , # [doc = " The amount of handles that don't affect our ability to compact our internal data structures or unload packs or indices."] pub (crate) num_handles_unstable : AtomicUsize , # [doc = " The amount of times we re-read the disk state to consolidate our in-memory representation."] pub (crate) num_disk_state_consolidation : AtomicUsize , # [doc = " If true, we are allowed to use multi-pack indices and they must have the `object_hash` or be ignored."] use_multi_pack_index : bool , # [doc = " The hash kind to use for some operations"] object_hash : gix_hash :: Kind , }
    };
}

Store!()